 p_id=>1
,p_name=>'Home'
,p_alias=>'HOME'
,p_step_title=>unistr('Florentino Lopez\00AE | Oracle Technology Blog')
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ==========================================================================',
unistr('   FLORENTINO LOPEZ\00AE'),
'   Oracle Technology Blog',
unistr('   Application 104 \2014 Public Home'),
'',
'   Oracle APEX 26.1.4',
'   Redwood Light',
'   ========================================================================== */',
'',
'',
'/* ==========================================================================',
'   01. DESIGN TOKENS',
'   ========================================================================== */',
'',
':root {',
'  --fl-bg: #f7f6f2;',
'  --fl-surface: #ffffff;',
'  --fl-surface-soft: #efede8;',
'',
'  --fl-ink: #1b1a18;',
'  --fl-muted: #6f6b66;',
