'',
'  --fl-dark: #151515;',
'  --fl-dark-soft: #211b19;',
'',
'  --fl-light-text: #f6f5f2;',
'',
'  --fl-max: 1320px;',
'}',
'',
'',
'/* ==========================================================================',
'   02. GLOBAL DOCUMENT',
'   ========================================================================== */',
'',
'html {',
'  scroll-behavior: smooth;',
'}',
'',
'body {',
'  margin: 0;',
'  background: var(--fl-bg);',
'  color: var(--fl-ink);',
'',
'  -webkit-font-smoothing: antialiased;',
'  -moz-osx-font-smoothing: grayscale;',
'}',
'',
'*,',
'*::before,',
'*::after {',
'  box-sizing: border-box;',
'}',
'',
'a {',
'  transition:',
'    color .18s ease,',
'    background-color .18s ease,',
'    border-color .18s ease,',
'    transform .18s ease;',
'}',
'',
'',
'/* ==========================================================================',
'   03. REMOVE STANDARD APEX PUBLIC CHROME',
'   Application 104 only',
'   ========================================================================== */',
'',
'.t-Header {',
'  display: none !important;',
'}',
'',
'.t-Body-title {',
'  display: none !important;',
'}',
'',
'.t-Footer {',
'  display: none !important;',
'}',
'',
'.t-Body,',
'.t-Body-main,',
'.t-Body-mainContent,',
'.t-Body-content,',
'.t-Body-contentInner {',
'  width: 100% !important;',
'  max-width: none !important;',
'  margin: 0 !important;',
'  background: var(--fl-bg);',
'}',
'',
'.t-Body-contentInner {',
'  padding: 0 !important;',
'}',
'',
'.t-Body-content {',
'  overflow-x: hidden;',
'}',
'',
'',
'/* ==========================================================================',
'   04. GENERIC PUBLIC SECTION',
'   ========================================================================== */',
'',
'.fl-section {',
'  width: min(var(--fl-max), calc(100% - 48px));',
'  margin: 0 auto !important;',
'  padding: 88px 0 !important;',
'}',
'',
'.fl-section--compact {',
'  padding-top: 60px !important;',
'  padding-bottom: 60px !important;',
'}',
'',
'.fl-section-label {',
'  margin: 0 0 18px;',
'',
'  color: var(--fl-red);',
'',
'  font-size: .68rem;',
'  font-weight: 700;',
'',
'  letter-spacing: .18em;',
'  text-transform: uppercase;',
'}',
'',
'.fl-section-title {',
'  margin: 0;',
'',
'  color: var(--fl-ink);',
'',
'  font-family:',
'    Georgia,',
'    "Times New Roman",',
'    serif;',
'',
'  font-size: clamp(2.1rem, 4vw, 4rem);',
'  font-weight: 400;',
'',
'  line-height: 1.04;',
'  letter-spacing: -.045em;',
'}',
'',
'.fl-section-intro {',
'  max-width: 720px;',
'  margin: 24px 0 0;',
'',
'  color: var(--fl-muted);',
'',
'  font-size: 1.05rem;',
'  line-height: 1.7;',
'}',
'',
'',
'/* ==========================================================================',
'   05. HERO REGION APEX RESET',
'   Static ID: fl-hero-region',
'   ========================================================================== */',
'',
'#fl-hero-region,',
'#fl-hero-region .t-Region,',
'#fl-hero-region .t-Region-bodyWrap,',
'#fl-hero-region .t-Region-body,',
'#fl-hero-region .t-Region-content {',
'  width: 100% !important;',
'  max-width: none !important;',
'',
'  margin: 0 !important;',
'  padding: 0 !important;',
'',
'  border: 0 !important;',
'  box-shadow: none !important;',
'',
'  background: transparent !important;',
'}',
'',
'',
'/* ==========================================================================',
'   06. HERO',
'   ========================================================================== */',
'',
'.fl-hero {',
'  display: grid;',
'',
'  grid-template-columns:',
'    minmax(0, 1.35fr)',
'    minmax(380px, .65fr);',
'',
'  width: 100%;',
'  min-height: 680px;',
'',
'  background: var(--fl-bg);',
'',
'  border-bottom: 1px solid var(--fl-line);',
'}',
'',
'',
'/* Left */',
'',
'.fl-hero__content {',
'  display: flex;',
'  flex-direction: column;',
'  justify-content: center;',
'',
'  padding: 88px 7vw 72px;',
'}',
'',
'.fl-hero__eyebrow {',
'  margin-bottom: 28px;',
'',
'  color: var(--fl-red);',
'',
'  font-size: .72rem;',
'  font-weight: 700;',
'',
'  letter-spacing: .22em;',
'  text-transform: uppercase;',
'}',
'',
'.fl-hero__title {',
'  max-width: 850px;',
'  margin: 0;',
'',
'  color: var(--fl-ink);',
'',
'  font-family:',
'    Georgia,',
'    "Times New Roman",',
'    serif;',
'',
'  font-size: clamp(4rem, 7vw, 7.5rem);',
'  font-weight: 400;',
'',
'  line-height: .94;',
'  letter-spacing: -.055em;',
'}',
'',
'.fl-hero__intro {',
'  max-width: 720px;',
'',
'  margin: 38px 0 0;',
'',
'  color: var(--fl-muted);',
'',
'  font-size: clamp(1.05rem, 1.35vw, 1.3rem);',
'  line-height: 1.7;',
'}',
'',
'',
'/* Buttons */',
'',
'.fl-hero__actions {',
'  display: flex;',
'  flex-wrap: wrap;',
'',
'  gap: 14px;',
'',
'  margin-top: 38px;',
'}',
'',
'.fl-btn {',
'  display: inline-flex;',
'',
'  align-items: center;',
'  justify-content: center;',
'',
'  min-height: 50px;',
'',
'  padding: 0 25px;',
'',
'  border-radius: 999px;',
'',
'  font-size: .92rem;',
'  font-weight: 600;',
'',
'  text-decoration: none !important;',
'}',
'',
'.fl-btn:hover {',
'  transform: translateY(-2px);',
'  text-decoration: none !important;',
'}',
'',
'.fl-btn--primary {',
'  color: #fff !important;',
'',
'  background: var(--fl-red);',
'',
'  border: 1px solid var(--fl-red);',
'}',
'',
'.fl-btn--primary:hover {',
'  color: #fff !important;',
'',
'  background: var(--fl-red-dark);',
'',
'  border-color: var(--fl-red-dark);',
'}',
'',
'.fl-btn--secondary {',
'  color: var(--fl-ink) !important;',
'',
'  background: transparent;',
'',
'  border: 1px solid #aaa49e;',
'}',
'',
'.fl-btn--secondary:hover {',
'  color: var(--fl-ink) !important;',
'',
'  background: #fff;',
'',
'  border-color: var(--fl-ink);',
'}',
'',
'',
'/* Technology tags */',
'',
'.fl-hero__meta {',
'  display: flex;',
'  flex-wrap: wrap;',
'',
'  gap: 26px;',
'',
'  margin-top: 70px;',
'',
'  color: var(--fl-soft-muted);',
'',
'  font-size: .68rem;',
'  font-weight: 700;',
'',
'  letter-spacing: .18em;',
'}',
'',
'',
'/* Right visual panel */',
'',
'.fl-hero__visual {',
'  position: relative;',
'',
'  display: flex;',
'  flex-direction: column;',
'  justify-content: space-between;',
'',
'  min-height: 680px;',
'',
'  padding: 58px 52px 48px;',
'',
'  overflow: hidden;',
'',
'  color: var(--fl-light-text);',
'',
'  background:',
'    radial-gradient(',
'      circle at 80% 15%,',
'      rgba(199, 70, 52, .16),',
'      transparent 34%',
