'',
'  border: 1px solid rgba(255, 255, 255, .07);',
'  border-radius: 50%;',
'}',
'',
'.fl-hero__visual-label,',
'.fl-hero__statement,',
'.fl-hero__visual-footer {',
'  position: relative;',
'  z-index: 2;',
'}',
'',
'.fl-hero__visual-label {',
'  color: #b7b3ae;',
'',
'  font-size: .68rem;',
'  font-weight: 700;',
'',
'  letter-spacing: .22em;',
'}',
'',
'.fl-hero__statement {',
'  font-family:',
'    Georgia,',
