'',
'  font-size: .7rem;',
'',
'  letter-spacing: .19em;',
'  text-transform: uppercase;',
'}',
'',
'',
'/* ==========================================================================',
'   07. FEATURED ARTICLE REGION',
'   CSS Class: fl-featured',
'   ========================================================================== */',
'',
'.fl-featured {',
'  width: min(var(--fl-max), calc(100% - 48px)) !important;',
'',
'  max-width: var(--fl-max) !important;',
'',
'  margin: 0 auto !important;',
'',
