 p_id=>wwv_flow_imp.id(13233752150981305)
,p_plug_name=>'Certifications'
,p_static_id=>'fl-certifications-region'
,p_title=>'Certifications'
,p_region_name=>'fl-certifications-region'
,p_region_css_classes=>'fl-certifications'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>60
,p_plug_grid_column_span=>12
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    id,',
'    name,',
'    issuer,',
'    credential_url,',
'    issued_date,',
'    expiration_date,',
'    case',
'        when expiration_date is not null then',
'            ''Issued '' ||',
'            to_char(issued_date, ''Mon YYYY'') ||',
unistr('            '' \00B7 Expires '' ||'),
'            to_char(expiration_date, ''Mon YYYY'')',
'        else',
'            ''Issued '' ||',
'            to_char(issued_date, ''Mon YYYY'')',
'    end as credential_meta',
'from certifications',
'where active_yn = true',
'order by',
'    issued_date desc nulls last,',
'    id desc',
'fetch first 6 rows only'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
