wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(13233371259981301)
,p_plug_name=>'Latest Articles'
,p_static_id=>'fl-latest-region'
,p_title=>'Latest Articles'
,p_region_name=>'fl-latest-region'
,p_region_css_classes=>'fl-latest'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>40
,p_plug_grid_column_span=>12
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with featured_post as (',
'    select p2.id',
'    from posts p2',
'    where p2.status = ''PUBLISHED''',
'    order by',
'        case',
'            when p2.featured_yn = true then 0',
'            else 1',
'        end,',
'        p2.published_at desc nulls last,',
'        p2.id desc',
'    fetch first 1 row only',
')',
'select',
'    p.id,',
'    p.title,',
'    p.slug,',
'    p.excerpt,',
'    p.featured_image_url,',
'    p.published_at,',
'    c.name as category_name,',
'    a.name as author_name',
'from posts p',
'left join categories c',
'    on c.id = p.category_id',
'left join authors a',
'    on a.id = p.author_id',
'where p.status = ''PUBLISHED''',
'  and p.id not in (',
'      select id',
'      from featured_post',
'  )',
'order by',
'    p.published_at desc nulls last,',
'    p.id desc',
'fetch first 3 rows only'))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
