wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(13234667476981314)
,p_plug_name=>'Public Article'
,p_static_id=>'fl-article-region'
,p_region_name=>'fl-article-region'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>3372714138756020509
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_html clob;',
'begin',
'',
'    for r in (',
'        select',
'            p.id,',
'            p.title,',
'            p.slug,',
'            p.excerpt,',
'            p.content,',
'            p.featured_image_url,',
'            p.published_at,',
'            c.name as category_name,',
'            a.name as author_name',
'        from posts p',
'        left join categories c',
'            on c.id = p.category_id',
'        left join authors a',
'            on a.id = p.author_id',
'        where p.id = :P2_POST_ID',
'          and p.status = ''PUBLISHED''',
'    )',
'    loop',
'',
'        l_html := to_clob(',
'            ''<article class="fl-article">',
'',
'                <div class="fl-article__top">',
'                    <a',
'                      class="fl-article__back"',
'                      href="/ords/r/trinity/florentino-lopez/home#fl-latest-region">',
unistr('                      \2190 Back to Articles'),
'                    </a>',
'                </div>',
'',
'                <header class="fl-article__header">',
'',
'                    <div class="fl-article__category">''',
'        );',
'',
'        l_html := l_html',
'            || apex_escape.html(r.category_name)',
'            || ''</div>'';',
'',
'        l_html := l_html',
'            || ''<h1 class="fl-article__title">''',
'            || apex_escape.html(r.title)',
'            || ''</h1>'';',
'',
'        if r.excerpt is not null then',
'            l_html := l_html',
'                || ''<p class="fl-article__excerpt">''',
'                || apex_escape.html(r.excerpt)',
'                || ''</p>'';',
'        end if;',
'',
'        l_html := l_html',
'            || ''<div class="fl-article__meta">'';',
'',
'        if r.author_name is not null then',
'            l_html := l_html',
'                || ''<span>''',
'                || apex_escape.html(r.author_name)',
'                || ''</span>'';',
'        end if;',
'',
'        if r.published_at is not null then',
'            l_html := l_html',
'                || ''<span>''',
'                || to_char(r.published_at, ''DD Mon YYYY'')',
'                || ''</span>'';',
'        end if;',
'',
'        l_html := l_html',
'            || ''</div>''',
'            || ''</header>'';',
'',
'        if r.featured_image_url is not null then',
'            l_html := l_html',
'                || ''<figure class="fl-article__media">''',
'                || ''<img src="''',
'                || apex_escape.html_attribute(r.featured_image_url)',
'                || ''" alt="''',
'                || apex_escape.html_attribute(r.title)',
'                || ''">''',
'                || ''</figure>'';',
'        end if;',
'',
'        l_html := l_html',
'            || ''<div class="fl-article__content">''',
'            || apex_escape.html_clob(r.content)',
'            || ''</div>'';',
'',
'        l_html := l_html',
'            || ''</article>'';',
'',
'        return l_html;',
'',
'    end loop;',
'',
'',
'    return to_clob(',
'        ''<section class="fl-article fl-article--empty">',
'            <h1>Article not found</h1>',
'            <p>The requested article is not available.</p>',
'            <a',
'              class="fl-article__back"',
'              href="/ords/r/trinity/florentino-lopez/home">',
unistr('              \2190 Return Home'),
'            </a>',
'        </section>''',
'    );',
'',
'end;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_created_on=>wwv_flow_imp.dz('20260908222151Z')
,p_updated_on=>wwv_flow_imp.dz('20260908222151Z')
,p_created_by=>'TRINITY_APP'
,p_updated_by=>'TRINITY_APP'
);
